import {BAG_PROMPTS} from './prompt-catalog.mjs';
import {day,monthsAgo} from './core.mjs';
export const GENERIC_PARTS=[
{part:0,name:'明确目标与交付',input:'任务描述、原始要求及可用附件',prompt:'区分用户要求、任务材料中的硬性要求、建议和待确认项。提取研究问题、范围、排除项、交付形式与验收条件。不得把尚未读取的附件当成已读。缺少非关键输入可说明假设后继续，关键决策以少量明确选项请用户决定。',output:'任务简报、范围与待确认问题',check:'要求可回溯，建议与硬性要求不混淆。'},
{part:1,name:'查找资料与案例',input:'已确认任务范围、既有资料与研究记忆',prompt:'先查已有记忆，安排复用、刷新、新搜。最新内容与过往热点并行研究，优先近三个月有可比证据的上升最快方向。实际搜索后记录原始链接、发布时间与采集时间、来源类型、可见指标和任务用途。同帖和同案例去重，独立复现保留。先小批发现，再按缺口扩展，不机械凑数量。',output:'可追溯资料、案例与缺口清单',check:'搜索入口和摘要不算已核验案例；不编造链接、日期和指标。'},
{part:2,name:'分析、核验与形成建议',input:'有来源的资料与案例',prompt:'围绕本任务问题逐条分析，分清事实、视觉观察、推断和预测。增长、当前热度和可信度分开；无可比时间数据标增长待验证，跨平台不直接相加。结合历史对照说明新生、持续或回潮，每条重要结论关联原始证据，保留反例、限制与待确认项。',output:'有依据的结论、比较与可执行建议',check:'结论与证据对应；预测标假设，样本不足不扩大判断。'},
{part:3,name:'交付与验收',input:'已核验分析和实际完成文件',prompt:'按用户选择的交付形式整理报告、案例库或学习方案。给出简明结论、证据索引、限制、后续动作。逐项检查硬性要求、数量、来源、图片和文件对应关系。缺失与无法判断分开，不把计划或Prompt当研究成果。生成可打开的实际文件后再称已交付。',output:'报告或案例库、引用与验收清单',check:'所有交付可打开、可复核，并明确尚未完成的部分。'}];
const WORK_ADDITIONS = [
'开放式社媒研究先定义可观察内容、场景和范围，不先限定风格名称或预设结论。精确查询已知对象时可直接搜索。',
'开放式社媒研究加载 references/work-discovery.md。以宽场景、分散作者的作品流、可用的相关作品/合集/模板关系和视觉相似入口发现候选；不要求标题或标签含具体风格词。视觉任务实际读取图片后再按结构归类，保留无标签、低互动及未命名的新组合。相关性筛选后再按时间与增长排序。具体关键词只用于补缺与核验。记录发现路径、平台/时间/内容角色覆盖、已读媒体数、新作者/结构、重复和不可读数量；同一推荐链重复时换独立入口。不能访问的能力标缺口，工具博客不能替代用户原帖。',
'检查样本是否过度来自同一作者、模板或推荐链；未读图不能按无关键词排除。保留原先分类之外的相关样本，必要时新增方向。未知总体不计算全网召回率；没有可比时间序列，不宣称近三个月增长最快。',
'交付实际覆盖与缺口，说明哪些相关样本由非具体风格关键词入口发现，多少完成媒体核验。跨独立入口连续两轮无相关增量可作为结束本轮的参考，不等于全平台覆盖。记忆保存发现路径与作者/内容关系，按新时段续查；较少重复不自动证明发现充分。'
];
const WORK_PARTS=GENERIC_PARTS.map((p,i)=>({...p,prompt:p.prompt+'\n'+WORK_ADDITIONS[i]}));
const BAG_OUTPUTS=['审美画像、三个探索方向及中英检索词','候选品牌与可比时间证据、两品牌建议','约100个去重素材及索引','两品牌外观变化及个人借鉴方法','趋势假设与四张风格卡','调研PPT逐页方案与讲稿','4×5矩阵与20款任务卡','绘制步骤、线稿审查及修改清单','四系列试色规则与20款上色要求','四款视图规格与三视图初稿要求','电子展板与实际文件验收清单'];
export function taskParts(task){if(task.profile==='bag-design')return BAG_PROMPTS.parts.map(p=>({...p,output:BAG_OUTPUTS[p.part],check:p.part===0?'用户未确认的审美方向不能记为确定偏好。':p.part===1?'有代表图、有年份依据、有可比较的视觉差异。':'满足本部分要求，引用真实编号与来源；缺失明确标注。'}));return task.mode==='work'?WORK_PARTS:GENERIC_PARTS;}
export function researchTask(input){const now=new Date();return {id:input.id,topic:input.topic.trim().slice(0,140),brief:input.topic.trim(),mode:input.mode,profile:input.profile==='bag-design'?'bag-design':'general',deliverable:input.deliverable||'研究简报',focus:input.focus||'',depth:'deep',start:monthsAgo(now,3),end:day(now),historyStart:monthsAgo(now,24),historyEnd:monthsAgo(now,3),created_at:now.toISOString(),plan_generated_at:now.toISOString(),attachments:input.attachments||[],workflow_progress:{},results:[]};}
export function fullPrompt(task,part){const common=task.profile==='bag-design'?BAG_PROMPTS.common:'你是面向工作与学习的证据研究助理。按需检索，尊重原始要求，事实、观察、推断、预测分开。';return `${common}\n\n使用 $startrail-search 执行以下部分。\n任务：${task.brief||task.topic}\n使用场景：${task.mode==='study'?'学习':'工作'}\n需要交付：${task.deliverable||'按照原任务要求'}\n关注重点：${task.focus||'依据任务和附件确定，不擅自增加要求'}\n\nPart ${part.part}｜${part.name}\n输入要求：${part.input}\n执行要求：\n${part.prompt}\n\n预期产物：${part.output}\n验收：${part.check}\n\n时间规则：优先近三个月有可比证据的最快上升趋势，同时研究最新内容及历史热点。历史必需范围不可被近期优先挤掉。无增长证据标待验证。\n附件：${(task.attachments||[]).map(f=>f.name).join('、')||'尚未附加；请只分析实际收到的内容'}\n先复用已验证资料再补缺，保留编号、来源和修改记录。未确定的审美、品牌、风格或试色等选择请用户决定，不擅自认定。前置缺失先说明并补充。不要把本Prompt或计划称为已完成的研究。\n\n结果回传：任务id=${task.id}。交付实际内容、来源和不足；可导出星迹schema_version:1的JSON，tasks中保留该任务，results每项含id、part、title、content、source、status、updated_at，文件含真实url或file_ref；workflow_progress写实际进度，不模拟运行。`;}
export function overview(task){const parts=taskParts(task);return {goal:task.brief||task.topic,deliverable:task.deliverable||'按照原任务交付',recent:`${task.start||monthsAgo(new Date(),3)} 至 ${task.end||day()}`,historical:`${task.historyStart||'按任务确定'} 至 ${task.historyEnd||'按任务确定'}`,parts:parts.length,source:task.profile==='bag-design'?BAG_PROMPTS.source_title:'星迹优化检索规则'};}
export function actualStage(task){const p=task.workflow_progress||{},values=Object.values(p);if(p.final?.status==='completed'||p.delivery?.status==='completed')return {index:3,label:'已交付',detail:'已记录完成；请查看实际文件与验收结果。'};if(values.some(x=>x.status==='needs_input'))return {index:1,label:'需要你确认',detail:'处理待确认项后，才能推进依赖它的部分。'};if(p.comparison?.status==='in_progress'||p.analysis?.status==='in_progress')return {index:2,label:'分析核验中',detail:'根据最近同步的进度显示。'};if(values.some(x=>x.status==='in_progress'))return {index:1,label:'资料研究中',detail:'这是已保存的进度，未连接自动执行服务。'};return {index:0,label:'方案已准备，等待执行',detail:'下一步复制执行任务或导出任务包，交给 Codex 继续。'};}
export function visibleResults(task){const rows=Array.isArray(task.results)?task.results:[];const replaced=new Set(rows.flatMap(r=>Array.isArray(r.supersedes)?r.supersedes:[]));return rows.filter(r=>!replaced.has(r.id));}
export function normalizeTask(task){const t={...task};t.mode=['study','学习'].includes(t.mode)?'study':'work';if(t.brief&&typeof t.brief==='object'){t.original_brief=t.brief;const b=t.brief;t.brief=[b.project||t.topic||'研究任务',Array.isArray(b.user_priority)?'重点：'+b.user_priority.join('、'):'',Array.isArray(b.excluded)?'排除：'+b.excluded.join('、'):''].filter(Boolean).join('\n');}t.topic=typeof t.topic==='string'?t.topic:typeof t.brief==='string'?t.brief.split('\n')[0]:'未命名任务';if(Array.isArray(t.focus))t.focus=t.focus.join('、');if(!t.profile)t.profile=t.mode==='study'&&t.original_brief?.requirements?.brands===2&&/20/.test(t.original_brief?.requirements?.week2||'')?'bag-design':'general';return t;}
